pub fn find_max_in_prefix(v: &[i32], end: usize) -> (i32, usize) {
    assert!(!v.is_empty(), "v must be non-empty");
    assert!(end < v.len(), "end must be within bounds");

    let mut best_val = v[0];
    let mut best_idx = 0usize;

    for i in 1..=end {
        let x = v[i];
        if x > best_val {
            best_val = x;
            best_idx = i;
        }
    }
    (best_val, best_idx)
}

pub fn find_min_in_suffix(v: &[i32], start: usize) -> (i32, usize) {
    assert!(!v.is_empty(), "v must be non-empty");
    assert!(start < v.len(), "start must be within bounds");

    let mut best_val = v[start];
    let mut best_idx = start;

    for i in (start + 1)..v.len() {
        let x = v[i];
        if x < best_val {
            best_val = x;
            best_idx = i;
        }
    }
    (best_val, best_idx)
}

pub fn barrier(v: &[i32], p: usize) -> bool {
    assert!(!v.is_empty(), "v must be non-empty");
    assert!(p < v.len(), "p must be within bounds");

    // Vacuously true if there is no element to the right of p.
    if p + 1 >= v.len() {
        return true;
    }

    let (max_left, _idx_left) = find_max_in_prefix(v, p);
    let (min_right, _idx_right) = find_min_in_suffix(v, p + 1);

    max_left < min_right
}

